// Diagnostic isolation: retain the public container and vanilla subscriptions, not its presentation or animation queue.
private var CanvasWatchSubscriptionsRestored:Boolean = false;

public function getCanvasWatchDataManager() : Object
{
   return BSUIDataManager;
}

public function getCanvasWatchDisabled() : Boolean
{
   return numChildren == 0 && !this.AlertTimer.running && !this.PlayingAnimation;
}

public function getCanvasWatchSubscriptionsRestored() : Boolean
{
   return this.CanvasWatchSubscriptionsRestored;
}

private function stopCanvasWatchTree(clip:MovieClip) : void
{
   clip.stop();
   for(var index:int = 0; index < clip.numChildren; index++)
   {
      var child:MovieClip = clip.getChildAt(index) as MovieClip;
      if(child != null)
      {
         this.stopCanvasWatchTree(child);
      }
   }
}

private function disableCanvasWatch() : void
{
   this.visible = false;
   this.stopCanvasWatchTree(this);
   this.AlertTimer.stop();
   this.AlertTimer.removeEventListener(TimerEvent.TIMER_COMPLETE,this.PlayNextInQueue);
   this.removeEventListener(ANIMATION_FINISHED,this.AnimationFinished);
   this.AnimationQueue = [];
   this.PlayingAnimation = false;
   this.CurrentAnimationName = "";
   while(numChildren > 0)
   {
      removeChildAt(0);
   }
}
